// 1. Unsigned Overflow (Defined behavior: Wraparound/Modulo N)
uint8_t u8_max = 255;
uint8_t result_u_ovf = u8_max + 1; // 0
// Unsigned underflow wraps to max value
uint8_t u8_min = 0;
uint8_t result_u_unf = u8_min - 1; // 255

// 2. Signed Overflow (C/C++: Undefined Behavior, typically wraps)
int8_t s8_max = 127;
int8_t result_s_ovf = s8_max + 1; // -128 (Implementation-dependent)

// 3. Detecting Overflow Before Operation
// Check if (a + b) > MAX_INT
if (a > INT_MAX - b) {
    // Overflow would occur
}
